import { test, describe } from 'node:test';
import assert from 'node:assert/strict';

import { runHandler } from '../src/api/router.ts';
import { router } from '../src/api/routes.ts';
import { loadEventsFor } from '../src/store/eventStore.ts';

function ctxFor(bookingId: string) {
  return {
    method: 'GET',
    pathname: `/bookings/${bookingId}/history`,
    params: { bookingId },
    query: new URLSearchParams(),
    body: undefined,
    userId: 'u-kanya',
    userRole: 'LECTURER',
  };
}

const route = (router as any).routes.find(
  (r: any) => r.method === 'GET' && r.pattern === '/bookings/:bookingId/history',
);

describe('REQ-41 ประวัติเหตุการณ์ของการจอง', () => {
  test('คืนเหตุการณ์ทั้งหมดของการจองที่มีอยู่ เรียงตามเวลา', async () => {
    const { status, payload } = await runHandler(route.handler, ctxFor('bk-seed-001'));
    assert.equal(status, 200);
    const events = payload as any[];
    assert.ok(events.length > 0);
    assert.ok(events.every((e) => e.bookingId === 'bk-seed-001'));
    for (let i = 1; i < events.length; i++) {
      assert.ok(
        new Date(events[i - 1].occurredAt).getTime() <= new Date(events[i].occurredAt).getTime(),
        'เหตุการณ์ต้องเรียงตามเวลาจากเก่าไปใหม่',
      );
    }
    assert.equal(events[0].type, 'BookingRequested');
  });

  test('loadEventsFor เรียงตามเวลาแม้เหตุการณ์ในไฟล์ไม่เรียงมาก่อน', () => {
    const events = loadEventsFor('bk-seed-001');
    const sorted = [...events].sort(
      (a, b) => new Date(a.occurredAt).getTime() - new Date(b.occurredAt).getTime(),
    );
    assert.deepEqual(events, sorted);
  });

  test('ไม่พบการจอง -> 404 รูปแบบ error มาตรฐาน (REQ-52)', async () => {
    const { status, payload } = await runHandler(route.handler, ctxFor('bk-does-not-exist'));
    assert.equal(status, 404);
    assert.equal((payload as any).error.code, 'BOOKING_NOT_FOUND');
  });
});

